CREATE COLUMN TABLE "TEST_AP"."AUGP" ("UgpEntry" INTEGER CS_INT NOT NULL , "UgpCode" NVARCHAR(20), "UgpName" NVARCHAR(100), "BaseUom" INTEGER CS_INT, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("UgpEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE 